(7488158, 1191883, 180710, '<td valign="top">The combination of the overcast/foggy sky with the smooth-textured deck, and no people in the photo, together with the strong light from the side, is stunning. I usually spend not more than a few seconds when voting on a photo; this one has been a few minutes.</td>', 'The combination of the overcast/foggy sky with the smooth-textured deck, and no people in the photo, together with the strong light from the side, is stunning. I usually spend not more than a few seconds when voting on a photo; this one has been a few minutes.', '2016-12-21 10:06:19.000000', NULL, 1),
(7488159, 1191986, 105457, '<td valign="top">The frame looks a bit big, but the meshup between trees and stone is very well done.</td>', 'The frame looks a bit big, but the meshup between trees and stone is very well done.', '2016-12-21 10:06:24.000000', NULL, 1),
